WITH due AS (SELECT o.item_id, o.owner_id, o.occurs_at, o.title, o.tz, o.all_day FROM ys_plan_occ(now() - interval '1 day', now() + interval '2 days') o JOIN ys_users u ON u.id = o.owner_id AND u.active WHERE o.remind_min IS NOT NULL AND o.occurs_at - make_interval(mins => o.remind_min) <= now() AND o.occurs_at - make_interval(mins => o.remind_min) > now() - interval '15 minutes' AND o.occurs_at > now() - interval '5 minutes'), ins AS (INSERT INTO ys_plan_sent (item_id, occurs_at) SELECT item_id, occurs_at FROM due ON CONFLICT DO NOTHING RETURNING item_id, occurs_at), nt AS (INSERT INTO ys_notifications (recipient_id, kind, title, body, link, actor_name) SELECT d.owner_id, 'plan_reminder', d.title, CASE WHEN d.all_day THEN 'Today' ELSE 'At ' || ltrim(to_char(d.occurs_at AT TIME ZONE d.tz, 'HH12:MI AM'), '0') END, '#/plan', 'My Plan' FROM due d JOIN ins ON ins.item_id = d.item_id AND ins.occurs_at = d.occurs_at RETURNING 1), tidy AS (DELETE FROM ys_plan_sent WHERE occurs_at < now() - interval '3 days' RETURNING 1) SELECT (SELECT count(*) FROM nt) AS reminders_sent
